import math
import pandas as pd
import ace_tools as tools

# Define the target harmonic value
H_target = 0.35
epsilon = 1e-5
max_depth = 5

# Recursive logic flowing function
def recursive_flow(value, depth, path, visited):
    if depth >= max_depth or (value, depth) in visited:
        return []

    visited.add((value, depth))
    results = []
    delta = abs(value - H_target)
    if delta < epsilon:
        results.append((value, delta, path))

    # Apply emergent logic transformations
    new_flows = []
    try:
        new_flows.append((value % 10, f"{path} -> mod10"))
    except:
        pass
    try:
        new_flows.append(((value + 1) % 10, f"{path} -> +1 mod10"))
    except:
        pass
    try:
        if value >= 0:
            new_flows.append((math.sqrt(value), f"{path} -> sqrt"))
    except:
        pass
    try:
        new_flows.append((math.exp(-value), f"{path} -> exp(-x)"))
    except:
        pass
    try:
        if value > 0:
            new_flows.append((math.log(value), f"{path} -> ln"))
    except:
        pass
    try:
        if value != 0:
            new_flows.append((1 / value, f"{path} -> inverse"))
    except:
        pass
    try:
        new_flows.append(((value**2 + 1)**0.5, f"{path} -> Pythagorean"))
    except:
        pass

    for new_val, new_path in new_flows:
        results.extend(recursive_flow(new_val, depth + 1, new_path, visited))

    return results

# Initialize seed values and run the recursive logic flow for each seed
seeds = [1.0, 4.0]
all_results = []
for seed in seeds:
    all_results.extend(recursive_flow(seed, 0, f"seed:{seed}", set()))

# Convert results to DataFrame and display
df = pd.DataFrame(all_results, columns=["Value", "Delta", "Path"])
df = df.sort_values(by="Delta")
tools.display_dataframe_to_user(name="Emergent Recursive Paths to H ≈ 0.35", dataframe=df)

import math
import itertools
import pandas as pd

# Base constants and known expressions
base_constants = {
    'pi': math.pi,
    'e': math.e,
    'ln2': math.log(2),
    'phi': (1 + math.sqrt(5)) / 2
}

# Initial expressions around 0.35
expressions = {
    'pi / 9': math.pi / 9,
    '1 / sqrt(8.16)': 1 / math.sqrt(8.16),
    'sqrt(1 / 8.163265)': math.sqrt(1 / 8.163265),
    'e^(-1.05)': math.exp(-1.05),
    'ln(1.4191)': math.log(1.4191)
}

# Recursive generator for logic emergence
def recursive_explore(expressions, depth=2):
    results = []
    expr_items = list(expressions.items())

    for d in range(1, depth + 1):
        for combo in itertools.combinations(expr_items, d):
            names = [x[0] for x in combo]
            values = [x[1] for x in combo]

            try:
                sum_expr = sum(values)
                results.append({'Expression': ' + '.join(names), 'Value': sum_expr})
            except Exception:
                pass

            try:
                prod_expr = math.prod(values)
                results.append({'Expression': ' * '.join(names), 'Value': prod_expr})
            except Exception:
                pass

            try:
                xor_expr = float(int(values[0]*1e9) ^ int(values[-1]*1e9)) / 1e9
                results.append({'Expression': f'xor({names[0]}, {names[-1]})', 'Value': xor_expr})
            except Exception:
                pass

            try:
                if values[-1] != 0:
                    div_expr = values[0] / values[-1]
                    results.append({'Expression': f'{names[0]} / {names[-1]}', 'Value': div_expr})
            except Exception:
                pass

    return pd.DataFrame(results)

df_emergent_logic = recursive_explore(expressions, depth=2)
import ace_tools as tools; tools.display_dataframe_to_user(name="Recursive Logic Emergence Near H ≈ 0.35", dataframe=df_emergent_logic)

# Reducing recursive exploration to a safer minimal depth for output rendering
df_emergent_logic_minimal = recursive_explore(expressions, depth=1)
import ace_tools as tools; tools.display_dataframe_to_user(name="Initial Recursive Logic Emergence Near H ≈ 0.35", dataframe=df_emergent_logic_minimal)

